pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title Web3BouncingBalls
 * @notice PvP On-chain game with Commit-Reveal scheme
 * @dev Optimized for stack depth and gas usage
 */
contract Web3BouncingBalls is ERC721, AccessControl, ReentrancyGuard {
    // ═══════════════════════════════════════════════════════════════
    // CUSTOM ERRORS
    // ═══════════════════════════════════════════════════════════════

    error InvalidStake();
    error GameDoesNotExist();
    error GameNotJoinable();
    error GameNotActive();
    error NotYourGame();
    error AlreadyCommitted();
    error AlreadyRevealed();
    error InvalidReveal();
    error CommitPhaseNotOver();
    error RevealPhaseOver();
    error NotOpponent();
    error NothingToWithdraw();
    error TransferFailed();
    error BallDoesNotExist();
    error NotBallOwner();
    error BallAlreadyInGame();
    error InvalidCommitment();
    error GameNotExpired();
    error MaxGamesReached();
    error InvalidInput();

    // ═══════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════

    event BallMinted(address indexed owner, uint256 indexed ballId, uint8 mass, uint8 elasticity);
    event GameCreated(uint256 indexed gameId, address indexed creator, uint256 stake);
    event GameJoined(uint256 indexed gameId, address indexed opponent);
    event MoveRevealed(uint256 indexed gameId, address indexed player);
    event GameResolved(uint256 indexed gameId, address indexed winner, uint256 prize);
    event GameCancelled(uint256 indexed gameId, address indexed canceller);
    event Withdrawal(address indexed user, uint256 amount);
    event TreasuryFunded(address indexed sender, uint256 amount);
    event FeeCollected(uint256 amount);

    // ═══════════════════════════════════════════════════════════════
    // CONSTANTS & CONFIG
    // ═══════════════════════════════════════════════════════════════

    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    uint256 public constant MAX_ATTRIBUTE = 100;
    uint256 public constant MIN_ATTRIBUTE = 10;
    uint256 public constant FEE_BPS = 250; // 2.5%
    uint256 public constant TIMEOUT_DURATION = 1 hours;
    uint256 public constant MAX_ACTIVE_GAMES_PER_USER = 5;

    // ═══════════════════════════════════════════════════════════════
    // STATE VARIABLES
    // ═══════════════════════════════════════════════════════════════

    struct BallStats {
        uint8 mass;
        uint8 elasticity;
        uint16 level;
        uint32 wins;
        uint64 lastAction;
        bool isBusy;
    }

    enum MatchState {
        WAITING,
        COMMITTED,
        REVEALED,
        RESOLVED,
        CANCELLED
    }

    // Tightly packed struct: 6 slots
    struct Game {
        // Slot 0 (32 bytes)
        address player1;       
        uint96 stake;          

        // Slot 1 (29 bytes used)
        address player2;       
        uint32 gameId;         
        uint32 deadline;       
        uint8 state;           

        // Slot 2 (26 bytes used)
        uint32 ball1Id;        
        uint32 ball2Id;        
        bool p1Revealed;       
        bool p2Revealed;       
        uint128 p1Secret;      

        // Slot 3 (16 bytes used)
        uint128 p2Secret;      

        // Slot 4 (32 bytes)
        bytes32 p1Commit;      

        // Slot 5 (32 bytes)
        bytes32 p2Commit;      
    }

    uint256 private _tokenIds;
    uint256 private _gameIds;

    mapping(uint256 => BallStats) public ballStats;
    mapping(uint256 => Game) public games;
    mapping(address => uint256) public pendingWithdrawals;
    mapping(address => uint256) public activeGameCount;

    uint256 public treasuryBalance;

    // ═══════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════

    constructor() ERC721("Web3 Bouncing Balls", "WBB") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(OPERATOR_ROLE, msg.sender);
    }

    receive() external payable {
        treasuryBalance += msg.value;
        emit TreasuryFunded(msg.sender, msg.value);
    }

    // ═══════════════════════════════════════════════════════════════
    // NFT MANAGEMENT
    // ═══════════════════════════════════════════════════════════════

    function mintBall() external nonReentrant returns (uint256) {
        uint256 newItemId;
        unchecked {
            ++_tokenIds;
            newItemId = _tokenIds;
        }

        uint256 random = uint256(keccak256(abi.encodePacked(
            block.timestamp, 
            msg.sender, 
            newItemId
        )));

        uint8 mass = uint8((random % (MAX_ATTRIBUTE - MIN_ATTRIBUTE)) + MIN_ATTRIBUTE);
        uint8 elasticity = uint8(((random >> 8) % (MAX_ATTRIBUTE - MIN_ATTRIBUTE)) + MIN_ATTRIBUTE);

        ballStats[newItemId] = BallStats({
            mass: mass,
            elasticity: elasticity,
            level: 1,
            wins: 0,
            lastAction: uint64(block.timestamp),
            isBusy: false
        });

        _safeMint(msg.sender, newItemId);
        emit BallMinted(msg.sender, newItemId, mass, elasticity);
        return newItemId;
    }

    // ═══════════════════════════════════════════════════════════════
    // GAMEPLAY
    // ═══════════════════════════════════════════════════════════════

    function createGame(uint256 ballId, bytes32 commitment) external payable nonReentrant returns (uint256) {
        if (msg.value == 0) revert InvalidStake();
        if (commitment == bytes32(0)) revert InvalidCommitment();
        if (activeGameCount[msg.sender] >= MAX_ACTIVE_GAMES_PER_USER) revert MaxGamesReached();

        _verifyOwnershipAndAvailability(ballId);

        ballStats[ballId].isBusy = true;

        uint256 gameId;
        unchecked {
            activeGameCount[msg.sender]++;
            ++_gameIds;
            gameId = _gameIds;
        }

        Game storage g = games[gameId];
        g.gameId = uint32(gameId);
        g.player1 = msg.sender;
        g.stake = uint96(msg.value);
        g.ball1Id = uint32(ballId);
        g.p1Commit = commitment;
        g.state = uint8(MatchState.WAITING);
        g.deadline = uint32(block.timestamp + TIMEOUT_DURATION);

        emit GameCreated(gameId, msg.sender, msg.value);
        return gameId;
    }

    function joinGame(uint256 gameId, uint256 ballId, bytes32 commitment) external payable nonReentrant {
        // Scoped to avoid stack issues
        Game storage g = games[gameId];

        if (g.state != uint8(MatchState.WAITING)) revert GameNotJoinable();
        if (msg.value != g.stake) revert InvalidStake();
        if (g.player1 == msg.sender) revert InvalidInput();
        if (commitment == bytes32(0)) revert InvalidCommitment();
        if (activeGameCount[msg.sender] >= MAX_ACTIVE_GAMES_PER_USER) revert MaxGamesReached();

        _verifyOwnershipAndAvailability(ballId);

        // Effect
        g.player2 = msg.sender;
        g.ball2Id = uint32(ballId);
        g.p2Commit = commitment;
        g.state = uint8(MatchState.COMMITTED);
        g.deadline = uint32(block.timestamp + TIMEOUT_DURATION);

        ballStats[ballId].isBusy = true;
        unchecked {
            activeGameCount[msg.sender]++;
        }

        emit GameJoined(gameId, msg.sender);
    }

    function revealMove(uint256 gameId, uint128 secret) external nonReentrant {
        bool readyToResolve = _registerReveal(gameId, secret, msg.sender);

        emit MoveRevealed(gameId, msg.sender);

        if (readyToResolve) {
            _resolveGame(gameId);
        }
    }

    function claimTimeout(uint256 gameId) external nonReentrant {
        // Reduced stack usage by delegating logic
        Game storage g = games[gameId];
        if (block.timestamp <= g.deadline) revert GameNotExpired();

        uint8 currentState = g.state;

        if (currentState == uint8(MatchState.WAITING)) {
            if (msg.sender != g.player1) revert NotYourGame();
            _refundP1(gameId);
        } else if (currentState == uint8(MatchState.COMMITTED) || currentState == uint8(MatchState.REVEALED)) {
            if (msg.sender != g.player1 && msg.sender != g.player2) revert NotYourGame();
            _handleActiveTimeout(gameId);
        } else {
            revert GameNotActive();
        }
    }

    // ═══════════════════════════════════════════════════════════════
    // INTERNAL LOGIC (Stack Optimized)
    // ═══════════════════════════════════════════════════════════════

    function _verifyOwnershipAndAvailability(uint256 ballId) internal view {
        if (ownerOf(ballId) != msg.sender) revert NotBallOwner();
        if (ballStats[ballId].isBusy) revert BallAlreadyInGame();
    }

    function _registerReveal(uint256 gameId, uint128 secret, address player) internal returns (bool) {
        Game storage g = games[gameId];
        uint8 currentState = g.state;

        if (currentState != uint8(MatchState.COMMITTED) && currentState != uint8(MatchState.REVEALED)) {
            revert GameNotActive();
        }

        // Verify commitment match
        bytes32 commit = (player == g.player1 ? g.p1Commit : g.p2Commit);
        if (keccak256(abi.encodePacked(secret, player)) != commit) {
            revert InvalidReveal();
        }

        if (player == g.player1) {
            if (g.p1Revealed) revert AlreadyRevealed();
            g.p1Secret = secret;
            g.p1Revealed = true;
        } else if (player == g.player2) {
            if (g.p2Revealed) revert AlreadyRevealed();
            g.p2Secret = secret;
            g.p2Revealed = true;
        } else {
            revert NotYourGame();
        }

        // If both revealed, return true to trigger resolution
        if (g.p1Revealed && g.p2Revealed) {
            return true;
        } 

        if (currentState == uint8(MatchState.COMMITTED)) {
            g.state = uint8(MatchState.REVEALED);
        }
        return false;
    }

    function _handleActiveTimeout(uint256 gameId) internal {
        Game storage g = games[gameId];

        if (g.state == uint8(MatchState.REVEALED)) {
            // One player revealed, one didn't. Revealed player wins by default.
            if (g.p1Revealed && !g.p2Revealed) {
                _forceWin(gameId, g.player1);
            } else if (!g.p1Revealed && g.p2Revealed) {
                _forceWin(gameId, g.player2);
            } else {
                _refundGame(gameId);
            }
        } else {
            // No one revealed -> Refund
            _refundGame(gameId);
        }
    }

    function _resolveGame(uint256 gameId) internal {
        // Optimized to avoid "Stack too deep" by only returning winner
        // and recalculating derived data where needed
        address winner = _determineWinner(gameId);

        Game storage g = games[gameId];
        uint32 winningBallId = (winner == g.player1) ? g.ball1Id : g.ball2Id;

        _applyResolution(gameId, winner, winningBallId);
    }

    // Returns only address to save stack slots
    function _determineWinner(uint256 gameId) internal view returns (address) {
        Game storage g = games[gameId];
        uint256 seed = uint256(keccak256(abi.encodePacked(g.p1Secret, g.p2Secret)));

        uint256 score1 = _calculateScore(g.ball1Id, seed % 100);
        uint256 score2 = _calculateScore(g.ball2Id, (seed >> 128) % 100);

        if (score1 >= score2) {
            return g.player1;
        } else {
            return g.player2;
        }
    }

    function _applyResolution(uint256 gameId, address winner, uint32 winningBallId) internal {
        Game storage g = games[gameId];
        g.state = uint8(MatchState.RESOLVED);

        _freeBalls(g.ball1Id, g.ball2Id);
        _decrementActiveGames(g.player1, g.player2);

        unchecked {
            ballStats[winningBallId].wins++;
        }

        // Use block scoping to limit variable lifespan
        {
            uint256 totalPot;
            uint256 fee;
            unchecked {
                totalPot = uint256(g.stake) * 2;
                fee = (totalPot * FEE_BPS) / 10000;
                treasuryBalance += fee;
                pendingWithdrawals[winner] += (totalPot - fee);
            }
            emit GameResolved(gameId, winner, totalPot - fee);
        }
    }

    function _forceWin(uint256 gameId, address winner) internal {
        Game storage g = games[gameId];
        uint32 winningBallId = (winner == g.player1) ? g.ball1Id : g.ball2Id;
        _applyResolution(gameId, winner, winningBallId);
    }

    function _calculateScore(uint256 ballId, uint256 seedVal) internal view returns (uint256) {
        BallStats storage b = ballStats[ballId];
        unchecked {
            return (uint256(b.elasticity) * seedVal) + (uint256(b.mass) * 10);
        }
    }

    function _refundGame(uint256 gameId) internal {
        Game storage g = games[gameId];
        g.state = uint8(MatchState.CANCELLED);

        _freeBalls(g.ball1Id, g.ball2Id);
        _decrementActiveGames(g.player1, g.player2);

        uint256 stakeAmount = g.stake;
        address p1 = g.player1;
        address p2 = g.player2;

        pendingWithdrawals[p1] += stakeAmount;
        pendingWithdrawals[p2] += stakeAmount;

        emit GameCancelled(gameId, msg.sender);
    }

    function _refundP1(uint256 gameId) internal {
        Game storage g = games[gameId];
        g.state = uint8(MatchState.CANCELLED);
        address p1 = g.player1;

        ballStats[g.ball1Id].isBusy = false;
        unchecked {
            activeGameCount[p1]--;
        }
        pendingWithdrawals[p1] += g.stake;
        emit GameCancelled(gameId, p1);
    }

    function _freeBalls(uint32 b1, uint32 b2) internal {
        ballStats[b1].isBusy = false;
        ballStats[b2].isBusy = false;
    }

    function _decrementActiveGames(address p1, address p2) internal {
        unchecked {
            if (activeGameCount[p1] > 0) activeGameCount[p1]--;
            if (activeGameCount[p2] > 0) activeGameCount[p2]--;
        }
    }

    // ═══════════════════════════════════════════════════════════════
    // FUNDS & VIEWS
    // ═══════════════════════════════════════════════════════════════

    function withdraw() external nonReentrant {
        uint256 amount = pendingWithdrawals[msg.sender];
        if (amount == 0) revert NothingToWithdraw();

        pendingWithdrawals[msg.sender] = 0;
        (bool success, ) = msg.sender.call{value: amount}("");
        if (!success) revert TransferFailed();

        emit Withdrawal(msg.sender, amount);
    }

    function withdrawTreasury(address to, uint256 amount) external onlyRole(DEFAULT_ADMIN_ROLE) nonReentrant {
        if (amount > treasuryBalance) revert InvalidInput();
        treasuryBalance -= amount;

        (bool success, ) = to.call{value: amount}("");
        if (!success) revert TransferFailed();
        emit FeeCollected(amount);
    }

    function getBallStats(uint256 ballId) external view returns (BallStats memory) {
        if (!_exists(ballId)) revert BallDoesNotExist();
        return ballStats[ballId];
    }

    function getGame(uint256 gameId) external view returns (
        address p1, 
        address p2, 
        uint256 stake, 
        uint8 state, 
        uint32 deadline
    ) {
        Game storage g = games[gameId];
        return (g.player1, g.player2, g.stake, g.state, g.deadline);
    }

    function supportsInterface(bytes4 interfaceId) public view override(ERC721, AccessControl) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}
